import { mergeIngredients } from './merge';

export async function getShoppingList(req, res) {
  const ids = String(req.query.recipes ?? '').split(',').filter(Boolean);
  const recipes = await recipesService.findMany(ids);
  if (recipes.length !== ids.length) {
    return res.status(400).json({ error: 'unknown recipe' });
  }
  res.json({ items: mergeIngredients(recipes) });
}

import { Checklist } from '../components/Checklist';
import { useShoppingList } from '../hooks/useShoppingList';

export function ShoppingListPage({ recipeIds }) {
  const { items, tick } = useShoppingList(recipeIds);
  return (
    <Checklist
      title="Shopping list"
      items={items.map((i) => ({ id: i.name, label: `${i.quantity} ${i.unit} ${i.name}`, done: i.done }))}
      onTick={tick}
    />
  );
}

export const TO_BASE = {
  g: 1,
  kg: 1000,
  ml: 1,
  l: 1000,
} as const;

export function format(quantity: number, unit: 'g' | 'ml') {
  if (quantity >= 1000) return `${quantity / 1000} ${unit === 'g' ? 'kg' : 'l'}`;
  return `${quantity} ${unit}`;
}
